# list_diff :: ([1, 2, 3, 4], [2, 4])
def list_diff(a, b):
    bset = set(b)
    return [x for x in a if x not in bset]

if __name__ == '__main__':
    print(list_diff(([1, 2, 3, 4], [2, 4])))

